import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as textureTSL } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Group();

  // Load texture
  const textureUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const tex = ctx.textureLoader.load(textureUrl);
  tex.colorSpace = THREE.SRGBColorSpace;

  // Calculate plane size from atlas region aspect ratio
  const atlasRect = config.atlasRegion?.sourceRect || [0, 0, 512, 320];
  const imgWidth = atlasRect[2] - atlasRect[0];
  const imgHeight = atlasRect[3] - atlasRect[1];
  const aspectRatio = imgWidth / imgHeight;

  // Create plane with appropriate size
  const planeWidth = 2.0;
  const planeHeight = planeWidth / aspectRatio;
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Create material using TSL texture node
  const texNode = textureTSL(tex);
  const material = new MeshBasicNodeMaterial({
    colorNode: texNode,
    transparent: true,
  });

  // Create mesh and apply transforms
  const mesh = new THREE.Mesh(geometry, material);

  const position = config.scenePosition || [-3.2, -0.3, 0];
  const rotation = config.sceneRotation || [0, 0, 0];
  const scale = config.sceneScale || [1, 1, 1];

  mesh.position.fromArray(position);
  mesh.rotation.order = 'XYZ';
  mesh.rotation.fromArray(rotation);
  mesh.scale.fromArray(scale);

  container.add(mesh);

  // Setup handlers and cleanup
  container.userData.handlers = {};
  container.userData.cleanup = function() {
    geometry.dispose();
    material.dispose();
    tex.dispose();
    gsap.killTweensOf(mesh);
  };

  return container;
}
